package dev.whistle.app.protocol

import dev.whistle.app.data.toEntity
import dev.whistle.app.data.toWire
import dev.whistle.app.ui.chat.toolSummary
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * C1: the bridge's real output for an oversized tool input (generated by the Go test
 * TestTruncatedToolInputFixture, copied from bridge/internal/server/testdata) must decode.
 */
class TruncatedInputTest {
    private val fixture = WireJson.parseToJsonElement(
        javaClass.getResource("/truncated_tool_call.json")!!.readText(),
    ).jsonObject

    @Test
    fun bridgeChangeFrameWithTruncatedInputDecodes() {
        val d = decodeServerFrame(fixture["change"].toString())
        assertTrue("decoded as $d", d is Decoded.Msg)
        val c = (d as Decoded.Msg).msg as Change
        val m = c.message!!
        assertTrue(m.truncated)
        val tr = m.input!!.jsonObject["_truncated"]!!.jsonPrimitive.content
        assertTrue(tr.startsWith("{"))
        assertEquals("/tmp/x", toolSummary(m))
        // Cache round trip keeps it.
        val back = m.toEntity("m1").toWire()
        assertEquals(m.input, back.toolInput)
    }

    @Test
    fun bridgeHistoryResultWithTruncatedInputDecodes() {
        val d = decodeServerFrame(fixture["history"].toString())
        assertTrue("decoded as $d", d is Decoded.Msg)
        val res = (d as Decoded.Msg).msg as Res
        val page = WireJson.decodeFromJsonElement(WHistoryPage.serializer(), res.result!!)
        assertEquals("toolu_big", page.messages.single().toolCallId)
    }

    @Test
    fun legacyStringInputIsTolerated() {
        val frame = """{"t":"change","seq":3,"kind":"message","session_key":"k","message":""" +
            """{"id":"a","seq":3,"session_key":"k","role":"tool_call","tool_name":"Bash","input":"{\"command\":\"ls -la\",\"x\":\"","truncated":true}}"""
        val d = decodeServerFrame(frame)
        assertTrue("decoded as $d", d is Decoded.Msg)
        val m = ((d as Decoded.Msg).msg as Change).message!!
        assertTrue((m.input as Any) is JsonPrimitive)
        assertEquals("ls -la", toolSummary(m))
        assertEquals(m.input, m.toEntity("m1").toWire().toolInput)
    }

    @Test
    fun summaryOfTruncatedObjectFallsBackToPrefix() {
        val m = WMessage("a", 1, "k", role = Role.TOOL_CALL, input = JsonObject(mapOf("_truncated" to JsonPrimitive("{\"weird\":[1,2"))))
        assertEquals("{\"weird\":[1,2", toolSummary(m))
    }
}
